struct Character {
    std::string_view id;
    const char* name;
    const char* icon_path;
    const char* portrait_path;
};

// Fixed compile-time catalog. Paths are UTF-8/ASCII literals; an empty path is
// allowed and means "no asset, use the caller's fallback".
inline constexpr std::array<Character, 2> characters{{
    {"player", u8"플레이어", "assets/player.png", "assets/player.png"},
    {"rook", u8"루크", "assets/bot.png", "assets/opponent.png"},
}};

inline constexpr std::string_view default_id="player";

bool select_character(std::string_view id) noexcept {
    const auto* entry = study_characters::find(id);
    if (!entry) return false;
    selected_id_ = entry->id;
    return true;
}

study_menu::Preferences preferences;
{
    std::string input = "rook";
    preferences.select_character(input);
} // input의 버퍼 수명 종료
// preferences.character_id()는 정적 리터럴 "rook"을 가리킨다.

const auto index = badge();
if (index >= badge_count - 1) return false;
selected_id_ = study_characters::characters[index + 1].id;
return true;

struct Art {
    Handle icon = 0;
    Handle portrait = 0;
    bool icon_fallback = false;
    bool portrait_fallback = false;
};

// ImageStore는 이미지 자원을 소유한다. ArtSet은 핸들만 빌린다.
study_image::ImageStore images(gl);
study_art::ArtSet art;

const std::string key(path);
const auto found = cache.find(key);
if (found != cache.end()) return found->second;
const Handle handle = load(key);
cache.emplace(key, handle);
return handle;

const Handle handle = acquire(load, cache, path);
if (handle != 0) {
    out = handle;
    out_fallback = false;
} else {
    out = fallback;
    out_fallback = true;
}

// 지역 candidate의 모든 항목을 채운 뒤
arts_ = candidate;
ready_ = true;
return true;

if (std::int64_t(box.width) * source_height <=
    std::int64_t(box.height) * source_width) {
    width = box.width;
    height = int(std::int64_t(box.width) * source_height / source_width);
} else {
    height = box.height;
    width = int(std::int64_t(box.height) * source_width / source_height);
}
// width와 height가 양수인 경우
return Rect{box.x + (box.width - width) / 2,
            box.y + (box.height - height) / 2, width, height};

inline bool valid(Rect box) noexcept {
    return box.width > 0 && box.height > 0 &&
        std::int64_t(box.x) + box.width <= (std::numeric_limits<int>::max)() &&
        std::int64_t(box.y) + box.height <= (std::numeric_limits<int>::max)();
}

const auto* selected_art = art.resolve(preferences.character_id());
if (!selected_art) return 1;
if (!study_art::draw_contained(images, art_quad, selected_art->icon,
                               {20,20,48,48})) return 1;
// 메뉴 화면에서만 큰 미리보기
if (app.screen() == study_app::Screen::menu &&
    !study_art::draw_contained(images, art_quad, selected_art->portrait,
                               {114,168,172,56})) return 1;

void presentation_draw_portrait(ImageHandle image, int x, int y, int w, int h) {
    int iw=0, ih=0;
    if (!image_size(image,iw,ih)) return;
    const auto fitted = image_fit::contain({x,y,w,h},iw,ih);
    if (fitted) draw_image(image,fitted->x,fitted->y,fitted->width,fitted->height);
}
